ALTER TABLE metal_work_order DROP CHECK chk_wo_status, ADD CONSTRAINT chk_wo_status CHECK(status IN ('PENDING','REJECTED','APPROVED','IN_PROGRESS','COMPLETED'));
CREATE TABLE metal_warehouse(warehouse_id BIGINT AUTO_INCREMENT PRIMARY KEY,factory_id BIGINT NOT NULL,name VARCHAR(100) NOT NULL,sort_order INT NOT NULL DEFAULT 0,status CHAR(1) NOT NULL DEFAULT '0',version INT NOT NULL DEFAULT 0,del_flag CHAR(1) NOT NULL DEFAULT '0',create_by VARCHAR(64) NOT NULL,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,update_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),UNIQUE(factory_id,name),CHECK(status IN ('0','1')));
CREATE TABLE metal_stock_sequence(sequence_date DATE NOT NULL,prefix VARCHAR(8) NOT NULL,sequence_value INT NOT NULL,PRIMARY KEY(sequence_date,prefix),CHECK(sequence_value BETWEEN 0 AND 999999));
CREATE TABLE metal_process_batch(batch_id BIGINT AUTO_INCREMENT PRIMARY KEY,request_id VARCHAR(36) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,request_actor BIGINT NOT NULL,factory_id BIGINT NOT NULL,work_order_id BIGINT NOT NULL,item_id BIGINT NOT NULL,process_id BIGINT NOT NULL,sequence_no INT NOT NULL,planned_quantity INT NOT NULL,completed_quantity INT NOT NULL DEFAULT 0,status VARCHAR(16) NOT NULL DEFAULT 'OPEN',version INT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),FOREIGN KEY(work_order_id) REFERENCES metal_work_order(work_order_id),FOREIGN KEY(item_id) REFERENCES metal_work_order_item(item_id),FOREIGN KEY(process_id) REFERENCES metal_process(process_id),CHECK(planned_quantity BETWEEN 1 AND 1000000),CHECK(completed_quantity BETWEEN 0 AND planned_quantity),CHECK(status IN ('OPEN','SETTLED','VOID')));
CREATE TABLE metal_inventory(inventory_id BIGINT AUTO_INCREMENT PRIMARY KEY,factory_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,category VARCHAR(16) NOT NULL,reference_id BIGINT NOT NULL,batch_no VARCHAR(160) NOT NULL DEFAULT '',code VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,specification VARCHAR(200),purity DECIMAL(12,6),organization VARCHAR(100),quantity BIGINT NOT NULL DEFAULT 0,net_weight DECIMAL(20,6) NOT NULL DEFAULT 0,origin_batch_id BIGINT,version INT NOT NULL DEFAULT 0,del_flag CHAR(1) NOT NULL DEFAULT '0',update_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),FOREIGN KEY(warehouse_id) REFERENCES metal_warehouse(warehouse_id),FOREIGN KEY(origin_batch_id) REFERENCES metal_process_batch(batch_id),UNIQUE(factory_id,warehouse_id,category,reference_id,batch_no),CHECK(category IN ('RAW','FINISHED','SEMI')),CHECK(quantity>=0 AND net_weight>=0),CHECK(purity IS NULL OR purity BETWEEN 0 AND 100));
CREATE TABLE metal_warehouse_order(order_id BIGINT AUTO_INCREMENT PRIMARY KEY,order_no VARCHAR(32) NOT NULL UNIQUE,request_id VARCHAR(36) NOT NULL UNIQUE,request_hash CHAR(64) NOT NULL,request_actor BIGINT NOT NULL,factory_id BIGINT NOT NULL,warehouse_id BIGINT NOT NULL,kind VARCHAR(16) NOT NULL,type VARCHAR(32) NOT NULL,order_date DATE NOT NULL,work_order_id BIGINT,batch_id BIGINT,operator_id BIGINT NOT NULL,keeper_id BIGINT NOT NULL,recipient_id BIGINT,inspector_id BIGINT,reviewer_id BIGINT,operator_name VARCHAR(100) NOT NULL,keeper_name VARCHAR(100) NOT NULL,recipient_name VARCHAR(100),inspector_name VARCHAR(100),reviewer_name VARCHAR(100),warehouse_name VARCHAR(100) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'POSTED',reason VARCHAR(500),version INT NOT NULL DEFAULT 0,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),FOREIGN KEY(warehouse_id) REFERENCES metal_warehouse(warehouse_id),FOREIGN KEY(work_order_id) REFERENCES metal_work_order(work_order_id),FOREIGN KEY(batch_id) REFERENCES metal_process_batch(batch_id),INDEX(batch_id),CHECK(status IN ('POSTED','VOID')),CHECK(kind IN ('OUT','IN','RET','ADJ')));
CREATE TABLE metal_warehouse_order_line(line_id BIGINT AUTO_INCREMENT PRIMARY KEY,order_id BIGINT NOT NULL,inventory_id BIGINT NOT NULL,source_line_id BIGINT,sequence_no INT NOT NULL,category VARCHAR(16) NOT NULL,reference_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,specification VARCHAR(200),batch_no VARCHAR(160) NOT NULL,net_weight DECIMAL(20,6) NOT NULL,quantity BIGINT NOT NULL DEFAULT 0,gross_weight DECIMAL(20,6),impurity DECIMAL(20,6),purity DECIMAL(12,6),organization VARCHAR(100),purpose VARCHAR(200),remark VARCHAR(500),FOREIGN KEY(order_id) REFERENCES metal_warehouse_order(order_id),FOREIGN KEY(inventory_id) REFERENCES metal_inventory(inventory_id),FOREIGN KEY(source_line_id) REFERENCES metal_warehouse_order_line(line_id),UNIQUE(order_id,sequence_no));
CREATE TABLE metal_stock_ledger(ledger_id BIGINT AUTO_INCREMENT PRIMARY KEY,inventory_id BIGINT NOT NULL,order_id BIGINT NOT NULL,line_id BIGINT NOT NULL,delta_weight DECIMAL(20,6) NOT NULL,delta_quantity BIGINT NOT NULL,balance_weight DECIMAL(20,6) NOT NULL,balance_quantity BIGINT NOT NULL,reversal_of BIGINT,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(inventory_id) REFERENCES metal_inventory(inventory_id),FOREIGN KEY(order_id) REFERENCES metal_warehouse_order(order_id),FOREIGN KEY(line_id) REFERENCES metal_warehouse_order_line(line_id),FOREIGN KEY(reversal_of) REFERENCES metal_stock_ledger(ledger_id),UNIQUE(reversal_of));
CREATE TABLE metal_warning_rule(rule_id BIGINT AUTO_INCREMENT PRIMARY KEY,factory_id BIGINT NOT NULL,product_id BIGINT NOT NULL,process_id BIGINT NOT NULL,tolerance DECIMAL(20,6) NOT NULL,status CHAR(1) NOT NULL DEFAULT '0',version INT NOT NULL DEFAULT 0,del_flag CHAR(1) NOT NULL DEFAULT '0',create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),FOREIGN KEY(product_id) REFERENCES metal_product(product_id),FOREIGN KEY(process_id) REFERENCES metal_process(process_id),UNIQUE(factory_id,product_id,process_id),CHECK(tolerance>=0),CHECK(status IN ('0','1')));
CREATE TABLE metal_work_report(report_id BIGINT AUTO_INCREMENT PRIMARY KEY,batch_id BIGINT NOT NULL UNIQUE,factory_id BIGINT NOT NULL,item_id BIGINT NOT NULL,process_id BIGINT NOT NULL,completed_quantity INT NOT NULL,issued_weight DECIMAL(20,6) NOT NULL,returned_weight DECIMAL(20,6) NOT NULL,loss_weight DECIMAL(20,6) NOT NULL,average_loss DECIMAL(20,6) NOT NULL,theoretical_loss DECIMAL(20,6) NOT NULL,tolerance DECIMAL(20,6) NOT NULL,threshold_value DECIMAL(20,6) NOT NULL,rule_id BIGINT,rule_version INT,status VARCHAR(16) NOT NULL,voided BOOLEAN NOT NULL DEFAULT FALSE,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(batch_id) REFERENCES metal_process_batch(batch_id),FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id),FOREIGN KEY(item_id) REFERENCES metal_work_order_item(item_id),FOREIGN KEY(process_id) REFERENCES metal_process(process_id),FOREIGN KEY(rule_id) REFERENCES metal_warning_rule(rule_id));
CREATE TABLE metal_report_material(report_material_id BIGINT AUTO_INCREMENT PRIMARY KEY,report_id BIGINT NOT NULL,code VARCHAR(64) NOT NULL,name VARCHAR(100) NOT NULL,issued_weight DECIMAL(20,6) NOT NULL,loss_weight DECIMAL(20,6) NOT NULL,average_loss DECIMAL(20,6) NOT NULL,FOREIGN KEY(report_id) REFERENCES metal_work_report(report_id));
CREATE TABLE metal_warning_record(warning_id BIGINT AUTO_INCREMENT PRIMARY KEY,report_id BIGINT NOT NULL UNIQUE,factory_id BIGINT NOT NULL,process_name VARCHAR(100) NOT NULL,product_category VARCHAR(100) NOT NULL,specification VARCHAR(200),order_no VARCHAR(32) NOT NULL,threshold_value DECIMAL(20,6) NOT NULL,theoretical_loss DECIMAL(20,6) NOT NULL,average_loss DECIMAL(20,6) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'PENDING',source_void BOOLEAN NOT NULL DEFAULT FALSE,result VARCHAR(500),handler_id BIGINT,handler_name VARCHAR(100),handled_time DATETIME,version INT NOT NULL DEFAULT 0,del_flag CHAR(1) NOT NULL DEFAULT '0',trigger_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(report_id) REFERENCES metal_work_report(report_id),FOREIGN KEY(factory_id) REFERENCES metal_factory(factory_id));
CREATE TABLE metal_warning_history(history_id BIGINT AUTO_INCREMENT PRIMARY KEY,warning_id BIGINT NOT NULL,action VARCHAR(32) NOT NULL,result VARCHAR(500),actor_id BIGINT NOT NULL,actor_name VARCHAR(100) NOT NULL,create_time DATETIME DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(warning_id) REFERENCES metal_warning_record(warning_id));
